create table envios (
  id bigint generated always as identity,
  creado timestamptz not null,
  deposito_id smallint not null,
  cliente_id int not null,
  estado text not null,
  bultos smallint not null,
  primary key (id, creado)
) partition by range (creado);

-- una partición por mes de 2026, con los límites a medianoche de Buenos Aires
do $$
declare m int;
begin
  for m in 1..12 loop
    execute format(
      'create table envios_2026_%s partition of envios for values from (%L) to (%L)',
      lpad(m::text, 2, '0'),
      make_timestamptz(2026, m, 1, 0, 0, 0, 'America/Argentina/Buenos_Aires'),
      make_timestamptz(2026 + (m / 12), 1 + (m % 12), 1, 0, 0, 0, 'America/Argentina/Buenos_Aires'));
  end loop;
end $$;

create table envios_resto partition of envios default;   -- lo que no cae en ningún mes
create index envios_creado on envios (creado);

-- en la base «coord»
create extension postgres_fdw;
create server shard_a foreign data wrapper postgres_fdw
  options (host '/var/tmp/r0930/sock', port '21301', dbname 'shard_a', batch_size '1000');
create user mapping for current_user server shard_a;
-- (lo mismo para shard_b y shard_c)

create table envios_s (id bigint not null, cliente_id int not null, creado timestamptz not null,
  deposito_id smallint not null, estado text not null, bultos smallint not null)
  partition by hash (cliente_id);

create foreign table envios_s_0 partition of envios_s for values with (modulus 3, remainder 0)
  server shard_a options (table_name 'envios_s');
create foreign table envios_s_1 partition of envios_s for values with (modulus 3, remainder 1)
  server shard_b options (table_name 'envios_s');
create foreign table envios_s_2 partition of envios_s for values with (modulus 3, remainder 2)
  server shard_c options (table_name 'envios_s');

