import hashlib

def h(k):   # hash estable: el hash() de Python cambia en cada ejecución
    return int.from_bytes(hashlib.md5(str(k).encode()).digest()[:8], "big")

claves = range(1, 1_000_001)

def movidos_modulo(n_viejo, n_nuevo):
    return sum(1 for k in claves if h(k) % n_viejo != h(k) % n_nuevo)

for a, b in [(3, 4), (4, 5), (8, 9)]:
    print(f"módulo {a}->{b}: {movidos_modulo(a, b) / len(claves):.1%} de las claves cambian de shard")
